import type { Ulid } from "@kurasu/contract/ulid";
import * as Context from "effect/Context";
import type * as Effect from "effect/Effect";

import type { Repository } from "../repository.ts";

export interface StoredSession extends Session {
  readonly enabled: boolean;
}

export interface NewSession extends SessionInput {
  readonly id: Ulid;
}

// Sessions stored in D1. Every read leaves out deleted sessions, and `remove`
// marks the session as deleted. `listEnabled` is the student's list, ordered
// by position and without `enabled`; `create` appends the session at the end,
// disabled and on slide 1, step 1; `reorder` receives every session not
// deleted, in the new order.
export class SessionsStore extends Context.Service<
  SessionsStore,
  Pick<
    Repository<StoredSession, NewSession, SessionChange>,
    "get" | "list" | "create" | "update" | "remove"
  > & {
    readonly listEnabled: () => Effect.Effect<ReadonlyArray<SessionSummary>>;
    readonly reorder: (ids: ReadonlyArray<Ulid>) => Effect.Effect<void>;
  }
>()("kurasu/SessionsStore") {}
import type { ClassroomTopic } from "@kurasu/contract/classroom";
import { OrderMismatch, SessionEnabled, SessionNotFound } from "@kurasu/contract/errors";
import type {
  Session,
  SessionChange,
  SessionInput,
  SessionSummary,
} from "@kurasu/contract/sessions";
import type { Ulid } from "@kurasu/contract/ulid";
import type { User } from "@kurasu/contract/user";
import * as Context from "effect/Context";
import * as Crypto from "effect/Crypto";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Option from "effect/Option";

import { Changelog } from "../changelog/changelog.ts";
import { Classroom } from "../classroom.ts";
import { SessionsStore, type StoredSession } from "./sessions-store.ts";
import { existingSession, visibleSession } from "./visible-session.ts";

const toSummary = (session: StoredSession): SessionSummary => ({
  id: session.id,
  title: session.title,
  summary: session.summary,
  position: session.position,
  enabled: session.enabled,
});

const toStudentSession = (session: StoredSession): Session => ({
  id: session.id,
  title: session.title,
  summary: session.summary,
  position: session.position,
  currentSlide: session.currentSlide,
  currentStep: session.currentStep,
});

// The topics a change to a session tells the classroom about: the teacher's
// position is `slide`; the rest of the session, enabling it included, is
// `session`.
const changedTopics = (change: SessionChange): ReadonlyArray<ClassroomTopic> => {
  const moved = change.currentSlide != null || change.currentStep != null;
  const edited = change.title != null || change.summary != null || change.enabled != null;

  return [...(edited ? ["session" as const] : []), ...(moved ? ["slide" as const] : [])];
};

// The sessions as each side sees them. The student sees only enabled sessions,
// without `enabled`; the featured one is the last of them. The teacher sees
// every session not deleted. A session is deleted only while disabled, and a
// reorder lists every session not deleted. A student enters only the classroom
// of the featured session; the teacher, that of any session not deleted.
export class Sessions extends Context.Service<
  Sessions,
  {
    readonly listVisible: () => Effect.Effect<ReadonlyArray<SessionSummary>>;
    readonly getVisible: (id: Ulid) => Effect.Effect<Session, SessionNotFound>;
    readonly featured: () => Effect.Effect<Option.Option<SessionSummary>>;
    readonly classroomOf: (viewer: User, id: Ulid) => Effect.Effect<void, SessionNotFound>;
    readonly listAll: () => Effect.Effect<ReadonlyArray<SessionSummary>>;
    readonly get: (id: Ulid) => Effect.Effect<Session, SessionNotFound>;
    readonly create: (input: SessionInput) => Effect.Effect<Session>;
    readonly update: (id: Ulid, change: SessionChange) => Effect.Effect<Session, SessionNotFound>;
    readonly remove: (id: Ulid) => Effect.Effect<void, SessionNotFound | SessionEnabled>;
    readonly reorder: (ids: ReadonlyArray<Ulid>) => Effect.Effect<void, OrderMismatch>;
  }
>()("kurasu/Sessions") {
  static readonly layer = Layer.effect(
    Sessions,
    Effect.gen(function* () {
      const store = yield* SessionsStore;
      const classroom = yield* Classroom;
      const changelog = yield* Changelog;
      const crypto = yield* Crypto.Crypto;

      const listVisible = () => store.listEnabled();

      const listAll = () => store.list({ orderBy: { field: "position", direction: "asc" } });

      const featured = () =>
        Effect.map(
          store.list({
            where: { enabled: true },
            orderBy: { field: "position", direction: "desc" },
            limit: 1,
          }),
          (sessions) => Option.map(Option.fromNullishOr(sessions[0]), toSummary),
        );

      return Sessions.of({
        listVisible,
        getVisible: (id) => visibleSession(store, id).pipe(Effect.map(toStudentSession)),
        featured,
        classroomOf: Effect.fn("Sessions.classroomOf")(function* (viewer, id) {
          if (viewer.role === "teacher") {
            return yield* existingSession(store, id).pipe(Effect.asVoid);
          }

          const session = Option.filter(yield* featured(), (found) => found.id === id);

          return yield* Effect.fromOption(session).pipe(
            Effect.mapError(() => new SessionNotFound()),
            Effect.asVoid,
          );
        }),
        listAll: () => Effect.map(listAll(), (sessions) => sessions.map(toSummary)),
        get: (id) => existingSession(store, id),
        create: Effect.fn("Sessions.create")(function* (input) {
          const id = yield* crypto.randomULID.pipe(Effect.orDie);

          return yield* store.create({ id, ...input });
        }),
        update: Effect.fn("Sessions.update")(function* (id, change) {
          const previous = yield* existingSession(store, id);

          const session = yield* Effect.fromOption(yield* store.update(id, change)).pipe(
            Effect.mapError(() => new SessionNotFound()),
          );

          yield* Effect.forEach(changedTopics(change), (topic) => classroom.notify(id, topic), {
            discard: true,
          });

          if (!previous.enabled && session.enabled) {
            yield* changelog.record({
              sessionId: id,
              type: "session-enabled",
              entityId: id,
              name: session.title,
            });
          }

          if (previous.enabled && !session.enabled) {
            yield* changelog.drop({ type: "session-enabled", entityId: id });
          }

          return session;
        }),
        remove: Effect.fn("Sessions.remove")(function* (id) {
          const session = yield* existingSession(store, id);

          if (session.enabled) {
            return yield* new SessionEnabled();
          }

          yield* store.remove(id);

          return yield* classroom.notify(id, "session");
        }),
        reorder: Effect.fn("Sessions.reorder")(function* (ids) {
          const current = new Set((yield* listAll()).map((session) => session.id));
          const requested = new Set(ids);

          const matches =
            ids.length === current.size &&
            requested.size === ids.length &&
            ids.every((id) => current.has(id));

          if (!matches) {
            return yield* new OrderMismatch();
          }

          return yield* store.reorder(ids);
        }),
      });
    }),
  );
}
import { SessionNotFound } from "@kurasu/contract/errors";
import type { Ulid } from "@kurasu/contract/ulid";
import * as Effect from "effect/Effect";

import type { SessionsStore, StoredSession } from "./sessions-store.ts";

// What the teacher may see of a session: any session that is not deleted.
export const existingSession = (
  sessions: SessionsStore["Service"],
  id: Ulid,
): Effect.Effect<StoredSession, SessionNotFound> =>
  Effect.flatMap(sessions.get(id), (session) =>
    Effect.fromOption(session).pipe(Effect.mapError(() => new SessionNotFound())),
  );

// What the student may see of a session: it exists, is not deleted and is
// enabled. A disabled, deleted or unknown session is the same 404.
export const visibleSession = (
  sessions: SessionsStore["Service"],
  id: Ulid,
): Effect.Effect<StoredSession, SessionNotFound> =>
  Effect.filterOrFail(
    existingSession(sessions, id),
    (session) => session.enabled,
    () => new SessionNotFound(),
  );

import {
  maxPage,
  type ListOptions,
  type Order,
  type RemoveOptions,
  type Repository,
  type UpsertOptions,
  type Where,
} from "@kurasu/core/repository";
import type { Ulid } from "@kurasu/contract/ulid";
import {
  and,
  type Assume,
  type InferInsertModel,
  type InferSelectModel,
  asc,
  count as countRows,
  desc,
  eq,
  getTableColumns,
  gt,
  inArray,
  isNotNull,
  isNull,
  lt,
  or,
  sql,
  type SQL,
} from "drizzle-orm";
import type {
  SQLiteColumn,
  SQLiteInsertValue,
  SQLiteTable,
  SQLiteUpdateSetSource,
} from "drizzle-orm/sqlite-core";
import type { EffectDrizzleQueryError } from "drizzle-orm/effect-core";
import * as DateTime from "effect/DateTime";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";

import { batch, Database, firstRow, now, type Statement } from "./database.ts";

export type Table = SQLiteTable & { readonly id: SQLiteColumn };

type New<T extends Table> = SQLiteInsertValue<T> & { readonly id: Ulid };

type Change<T extends Table> = Partial<InferInsertModel<T>>;

export interface RepositoryOptions<T extends Table, A> {
  readonly decode: (row: InferSelectModel<T>) => Effect.Effect<A>;
  readonly deletedAt?: SQLiteColumn;
}

// A value of the core goes to the column as the driver expects it: a DateTime
// becomes the Date that a timestamp column maps.
const toColumnValue = <V>(value: V) =>
  DateTime.isDateTime(value) ? DateTime.toDateUtc(value) : value;

const decodeAll = <T extends Table, A>(
  rows: ReadonlyArray<InferSelectModel<T>>,
  decode: RepositoryOptions<T, A>["decode"],
) => Effect.forEach(rows, decode);

type Write<R> = Statement & Effect.Effect<R, EffectDrizzleQueryError>;

const rowsGuardOf =
  <T extends Table>() =>
  <R>(rows: R): rows is R & ReadonlyArray<InferSelectModel<T>> =>
    Array.isArray(rows);

const ordersOf = <A>(orderBy: ListOptions<A>["orderBy"]): ReadonlyArray<Order<A>> =>
  orderBy == null ? [] : "field" in orderBy ? [orderBy] : orderBy;

const nullsOf = <A>(order: Order<A>) =>
  order.nulls ?? (order.direction === "asc" ? "first" : "last");

/**
 * The shared operations of a D1 store over one table, as the core's
 * `Repository` declares them. Every row read goes through `decode`. With
 * `deletedAt`, reads leave out the rows that have it set and `remove` sets it.
 */
export const repositoryOf = <T extends Table, A extends { readonly id: Ulid }>(
  table: T,
  { decode, deletedAt }: RepositoryOptions<T, A>,
) =>
  Effect.gen(function* () {
    const { db, client } = yield* Database;
    const columns: Record<string, SQLiteColumn | undefined> = getTableColumns(table);

    const columnOf = (field: string) => {
      const column = columns[field];

      return column == null
        ? Effect.die(`${field} is not a column of the table`)
        : Effect.succeed(column);
    };

    const notDeleted = deletedAt == null ? undefined : isNull(deletedAt);

    const propertyOf = (column: SQLiteColumn) =>
      Object.entries(columns).find(([, candidate]) => candidate === column)?.[0] ?? column.name;

    const conditionOf = (where: Where<A> | undefined) =>
      Effect.map(
        Effect.forEach(Object.entries(where ?? {}), ([field, value]) =>
          Effect.map(columnOf(field), (column) =>
            value == null
              ? isNull(column)
              : Array.isArray(value)
                ? inArray(column, value.map(toColumnValue))
                : eq(column, toColumnValue(value)),
          ),
        ),
        (conditions) => and(notDeleted, ...conditions),
      );

    // The rows after `after` in the given order: those past it on the first
    // field, or tied on it and past it on the next, and so on.
    interface Key {
      readonly column: SQLiteColumn;
      readonly value: unknown;
      readonly direction: Order<A>["direction"];
      readonly nulls: "first" | "last";
    }

    const tiedWith = (key: Key) =>
      key.value == null ? isNull(key.column) : eq(key.column, key.value);

    // The rows that sort after the key's value. A comparison with null is never
    // true, so the nulls join the following rows only when they go last, and a
    // null value is followed by every non-null when the nulls go first.
    const followingOf = (key: Key) => {
      if (key.value == null) {
        return key.nulls === "first" ? isNotNull(key.column) : sql`0`;
      }

      const beyond =
        key.direction === "asc" ? gt(key.column, key.value) : lt(key.column, key.value);

      return key.nulls === "last" ? or(beyond, isNull(key.column)) : beyond;
    };

    const afterOf = (orders: ReadonlyArray<Order<A>>, after: A) =>
      Effect.map(
        Effect.forEach(orders, (order) =>
          Effect.map(columnOf(order.field), (column) => ({
            column,
            value: toColumnValue(after[order.field]),
            direction: order.direction,
            nulls: nullsOf(order),
          })),
        ),
        (keys) =>
          or(
            ...keys.map((key, index) =>
              and(...keys.slice(0, index).map(tiedWith), followingOf(key)),
            ),
          ),
      );

    const byId = (id: Ulid) => and(eq(table.id, id), notDeleted);

    const get = (id: Ulid) =>
      db
        .select()
        .from(table)
        .where(byId(id))
        .limit(1)
        .pipe(Effect.orDie, Effect.flatMap(firstRow(decode)));

    const getMany = (ids: ReadonlyArray<Ulid>) =>
      ids.length === 0
        ? Effect.succeed([])
        : db
            .select()
            .from(table)
            .where(and(inArray(table.id, [...ids]), notDeleted))
            .orderBy(asc(table.id))
            .pipe(
              Effect.orDie,
              Effect.flatMap((rows) => decodeAll(rows, decode)),
            );

    // drizzle maps the rows that `.returning()` gives back to the table's select
    // model, but over a generic table it types them with a conditional it does
    // not resolve, and it cannot type a set with a computed key or the set of
    // `onConflictDoUpdate`. These guards give those values the types drizzle
    // cannot.
    const areRows = rowsGuardOf<T>();

    const namesColumns = (keys: ReadonlyArray<string>) => keys.every((key) => columns[key] != null);

    const isChange = <R extends object>(change: R): change is R & Change<T> =>
      namesColumns(Object.keys(change));

    const isConflictSet = <R extends object>(
      change: R,
    ): change is R & SQLiteUpdateSetSource<Assume<T, SQLiteTable>> =>
      namesColumns(Object.keys(change));

    const deletion = (column: SQLiteColumn) => {
      const mark = { [propertyOf(column)]: now };

      return isChange(mark)
        ? Effect.succeed(mark)
        : Effect.die(`${column.name} is not a column of the table`);
    };

    const removing = (condition: SQL | undefined): Effect.Effect<Write<unknown>> =>
      deletedAt == null
        ? Effect.succeed(db.delete(table).where(condition).returning())
        : Effect.map(deletion(deletedAt), (mark) =>
            db.update(table).set(mark).where(condition).returning(),
          );

    const removeReturning = (condition: SQL | undefined) =>
      Effect.gen(function* () {
        const rows = yield* (yield* removing(condition)).pipe(Effect.orDie);

        return areRows(rows)
          ? yield* decodeAll(rows, decode)
          : yield* Effect.die("the removed rows did not come back");
      });

    // A statement reads nothing after its write, so several can go in one D1
    // batch.
    const statements = {
      create: (row: New<T>) => db.insert(table).values(row),
      update: (id: Ulid, change: Change<T>) =>
        db.update(table).set(change).where(byId(id)).returning({ id: table.id }),
      updateWhere: (where: Where<A>, change: Change<T>) =>
        Effect.map(conditionOf(where), (condition) =>
          db.update(table).set(change).where(condition).returning({ id: table.id }),
        ),
      upsert: (row: New<T>, { target, set }: UpsertOptions<keyof New<T> & string, Change<T>>) =>
        Effect.gen(function* () {
          const targetColumns = yield* Effect.forEach(target, columnOf);
          const insert = db.insert(table).values(row);

          if (set == null) {
            return insert.onConflictDoNothing({ target: targetColumns });
          }

          return isConflictSet(set)
            ? insert.onConflictDoUpdate({ target: targetColumns, set })
            : yield* Effect.die("the set names a field that is not a column of the table");
        }),
      remove: (id: Ulid) => removing(byId(id)),
      removeWhere: (where: Where<A>) => Effect.flatMap(conditionOf(where), removing),
    };

    function removeWhere(where: Where<A>): Effect.Effect<number>;
    function removeWhere(where: Where<A>, options: RemoveOptions): Effect.Effect<ReadonlyArray<A>>;
    function removeWhere(
      where: Where<A>,
      options?: RemoveOptions,
    ): Effect.Effect<number | ReadonlyArray<A>> {
      if (options?.returning === true) {
        return Effect.flatMap(conditionOf(where), removeReturning);
      }

      return Effect.gen(function* () {
        const rows = yield* (yield* statements.removeWhere(where)).pipe(Effect.orDie);

        return areRows(rows)
          ? rows.length
          : yield* Effect.die("the removed rows did not come back");
      });
    }

    type Shared = Repository<A, New<T>, Change<T>>;

    return {
      statements,
      batch: (writes: ReadonlyArray<Statement>) => batch(client, writes),
      get,
      getMany,
      find: (where: Where<A>): ReturnType<Shared["find"]> =>
        Effect.gen(function* () {
          const rows = yield* db
            .select()
            .from(table)
            .where(yield* conditionOf(where))
            .orderBy(asc(table.id))
            .limit(1)
            .pipe(Effect.orDie);

          return yield* firstRow(decode)(rows);
        }),
      list: (options: ListOptions<A> = {}): ReturnType<Shared["list"]> =>
        Effect.gen(function* () {
          const orders: ReadonlyArray<Order<A>> = [
            ...ordersOf(options.orderBy),
            { field: "id", direction: "asc" },
          ];

          const keys = yield* Effect.forEach(orders, (order) =>
            Effect.map(
              columnOf(order.field),
              (column) =>
                sql`${order.direction === "asc" ? asc(column) : desc(column)} nulls ${sql.raw(nullsOf(order))}`,
            ),
          );

          const condition = and(
            yield* conditionOf(options.where),
            options.after == null ? undefined : yield* afterOf(orders, options.after),
          );

          const rows = yield* db
            .select()
            .from(table)
            .where(condition)
            .orderBy(...keys)
            .limit(Math.min(options.limit ?? maxPage, maxPage))
            .pipe(Effect.orDie);

          return yield* decodeAll(rows, decode);
        }),
      count: (where?: Where<A>): ReturnType<Shared["count"]> =>
        Effect.gen(function* () {
          const rows = yield* db
            .select({ count: countRows() })
            .from(table)
            .where(yield* conditionOf(where))
            .pipe(Effect.orDie);

          return rows[0]?.count ?? 0;
        }),
      create: (row: New<T>): ReturnType<Shared["create"]> =>
        statements.create(row).pipe(
          Effect.orDie,
          Effect.andThen(get(row.id)),
          Effect.flatMap(
            Option.match({
              onNone: () => Effect.die("the new row was not stored"),
              onSome: Effect.succeed,
            }),
          ),
        ),
      createMany: (rows: ReadonlyArray<New<T>>): ReturnType<Shared["createMany"]> =>
        rows.length === 0
          ? Effect.succeed([])
          : db
              .insert(table)
              .values([...rows])
              .pipe(Effect.orDie, Effect.andThen(getMany(rows.map((row) => row.id)))),
      update: (id: Ulid, change: Change<T>): ReturnType<Shared["update"]> =>
        Object.keys(change).length === 0
          ? get(id)
          : statements.update(id, change).pipe(
              Effect.orDie,
              Effect.flatMap((rows) => (rows.length === 0 ? Effect.succeedNone : get(id))),
            ),
      updateWhere: (where: Where<A>, change: Change<T>): ReturnType<Shared["updateWhere"]> =>
        Effect.gen(function* () {
          const rows = yield* (yield* statements.updateWhere(where, change)).pipe(Effect.orDie);

          return rows.length;
        }),
