  }

  useEffect(() => {
    if (sessions.data != null && (highlighted == null || highlighted !== entered)) {
      void navigate({ to: "/" });
    }
  }, [entered, highlighted, navigate, sessions.data]);

  return entered == null ? (
    <StudentClassroomSkeleton />
  ) : (
    <StudentClassroom key={entered} sessionId={entered} />
  );
};

