      {open && showResults && poll.results != null ? (
        <PollResults
          type={poll.type}
          results={poll.results}
          options={poll.options}
          scaleLabels={scaleLabelsOf(poll)}
          mine={mine}
          showCounts={showCounts}
        />
      ) : null}
      {open ? actions : null}
    </article>
  );
};
